{"command":["bash","-lc","python - <<'PY'
import json,numpy as np
rows=[r['result'] for r in map(json.loads,open('/app/lab_log.jsonl')) if r['op']=='decontaminate']
def f(c,m,l):
 x,y,z=c-1,m-1,l-1
 return [1,x,y,z,x*x,y*y,z*z,x*y,x*z,y*z]
A=np.array([f(**{'c':r['config']['capacity'],'m':r['config']['mixture'],'l':r['config']['lr_scale']}) for r in rows]);b=np.array([r['offline_slice_decontaminated'] for r in rows]);p=np.linalg.lstsq(A,b,rcond=None)[0]
print('coeff',p,'residual',b-A@p)
for q in [(1,1,1),(.5394,.5485,1.3887),(1,.5485,1.3887),(.5394,1,1.3887),(.5394,.5485,1),(1,1,1.3887),(1,.5485,1),(.5394,1,1)]:print(q,np.dot(f(*q),p))
PY"],"timeout_ms":150000,"workdir":"/app"}

